"""Recipe catalog backing the offline fake LLM (used when ANTHROPIC_API_KEY is unset, and in tests).

Ingredient tuple: (name, quantity, unit, store_section, cost_usd_for_that_quantity)
"""
from typing import Dict, List


def _r(name, slots, minutes, cal, protein, ings, steps):
    ingredients = [dict(name=n, quantity=q, unit=u, section=s, cost=c) for n, q, u, s, c in ings]
    return dict(
        name=name, slots=slots, cook_minutes=minutes, calories=cal, protein=protein,
        cost=round(sum(i["cost"] for i in ingredients), 2), steps=steps, ingredients=ingredients,
    )


